const $=id=>document.getElementById(id);let token='',page=1,jpage=1,total=0,jtotal=0,invoiceQuery='',invoiceState='';
const pageSize=document.createElement('select');pageSize.setAttribute('aria-label','Éléments par page des listes financières');for(const n of [10,25,50])pageSize.append(new Option(n+' par page',n));const sizeLabel=document.createElement('label');sizeLabel.textContent='Taille des listes financières';sizeLabel.append(pageSize);$('workspace').prepend(sizeLabel);const limit=()=>Number(pageSize.value);
const invoiceFilters=document.createElement('form');invoiceFilters.className='toolbar';invoiceFilters.setAttribute('aria-label','Filtres des créances');
const invoiceSearch=document.createElement('input');invoiceSearch.type='search';invoiceSearch.maxLength=180;invoiceSearch.placeholder='Référence, mission ou devise';invoiceSearch.setAttribute('aria-label','Rechercher une créance');
const invoiceStatus=document.createElement('select');invoiceStatus.setAttribute('aria-label','Statut des créances');for(const [value,label] of [['','Tous les statuts'],['OPEN','À encaisser'],['OVERDUE','En retard'],['PAID','Soldées']])invoiceStatus.append(new Option(label,value));
const invoiceSubmit=document.createElement('button');invoiceSubmit.textContent='Rechercher';invoiceFilters.append(invoiceSearch,invoiceStatus,invoiceSubmit);$('payment').before(invoiceFilters);
const invoiceHint=document.createElement('p');invoiceHint.textContent='Les filtres portent sur tout le registre. Les synthèses et la balance âgée restent globales.';invoiceFilters.after(invoiceHint);
invoiceFilters.onsubmit=e=>{e.preventDefault();invoiceQuery=invoiceSearch.value.trim();invoiceState=invoiceStatus.value;page=1;safe(load)};
const notice=s=>$('notice').textContent=s;
async function api(path,method='GET',data){const r=await fetch('/api/admin/'+path,{method,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error);return d}
async function safe(fn){try{await fn()}catch(e){notice(e.message)}}
function row(parent,values){const r=document.createElement('tr');for(const v of values){const c=document.createElement('td');c.textContent=v;r.append(c)}parent.append(r);return r}
function options(id,items,label,key='id'){const s=$(id),previous=s.value;s.replaceChildren(new Option('Sélectionner',''));for(const x of items)s.append(new Option(label(x),x[key]));if(items.some(x=>x[key]===previous))s.value=previous}
async function lookup(){const t=token,d=await api('missions?page='+encodeURIComponent($('mission-page').value));if(!token||t!==token)return;const label=m=>m.company+' / '+m.title+' ('+m.currency+')';options('milestone-mission',d.items.filter(m=>m.mode==='FORFAIT'),label,'mission_id');options('invoice-mission',d.items,label,'mission_id');options('schedule-mission',d.items,label,'mission_id');options('expense-mission',d.items,label,'mission_id');$('expense-mission').options[0].textContent='Sans mission'}
const listFilters={};
function addListSearch(id,label,reset,loader){
 const field=document.createElement('input'),wrapper=document.createElement('label');
 field.type='search';field.maxLength=180;field.placeholder='Rechercher…';field.setAttribute('aria-label',label);
 wrapper.className='finance-search';wrapper.textContent=label;wrapper.append(field);
 $(id).closest('.table-wrap').before(wrapper);
 const filter=listFilters[id]={field,query:'',sequence:0,timer:null};
 field.oninput=()=>{clearTimeout(filter.timer);filter.sequence++;if(!token)return;filter.timer=setTimeout(()=>{
  if(!token)return;filter.query=field.value.trim();reset();safe(loader);
 },350)};
}
let loadSequence=0;
async function load(){const t=token,seq=++loadSequence,d=await api('billing?'+new URLSearchParams({page,q:invoiceQuery,state:invoiceState,page_size:limit()}));if(!token||t!==token||seq!==loadSequence)return;total=d.total;if(page>Math.max(1,Math.ceil(total/limit()))){page=Math.max(1,Math.ceil(total/limit()));return load()}for(const id of ['rows','totals'])$(id).replaceChildren();for(const [c,v] of Object.entries(d.totals))row($('totals'),[c,v.invoiced,v.paid,v.balance,v.overdue]);for(const x of d.items)row($('rows'),[x.reference+' / '+x.title,x.amount+' '+x.currency,x.paid,x.balance,x.due_date,x.overdue?'En retard':Number(x.balance)===0?'Soldée':'À encaisser']);options('payment-invoice',d.items.filter(x=>Number(x.balance)>0),x=>x.reference+' / '+x.balance+' '+x.currency);$('page').textContent='Page '+page+' / '+Math.max(1,Math.ceil(total/limit()))+' · '+total+' créance(s)';$('prev').disabled=page===1;$('next').disabled=page*limit()>=total;await Promise.all([loadMilestones(),loadExpenses(),loadContracts(),loadSchedule(),loadCollections(),loadForecast(),loadBudget()])}
async function loadMilestones(){const filter=listFilters['milestone-rows'],seq=++filter.sequence,t=token,j=await api('billing/milestones?'+new URLSearchParams({page:jpage,q:filter.query,page_size:limit()}));if(!token||t!==token||seq!==filter.sequence)return;jtotal=j.total;$('milestone-rows').replaceChildren();for(const x of j.items){const r=row($('milestone-rows'),[x.mission_title,x.title,x.amount+' '+x.currency,x.status,'']);if(x.status==='PREVU'){const b=document.createElement('button');b.textContent='Valider';b.onclick=()=>safe(async()=>{if(!confirm('Valider définitivement ce jalon ?'))return;await api('billing/milestones/'+x.id,'PATCH',{status:'VALIDE'});await load()});r.lastChild.append(b)}}$('jpage').textContent='Page '+jpage+' · '+jtotal+' jalon(s)';$('jprev').disabled=jpage===1;$('jnext').disabled=jpage*limit()>=jtotal;}
$('login-form').onsubmit=async e=>{e.preventDefault();token=$('token').value;$('token').value='';try{await load();await lookup();$('login').hidden=true;$('workspace').hidden=false}catch(e){token='';notice(e.message)}};
$('logout').onclick=()=>{token='';loadSequence++;for(const filter of Object.values(listFilters)){clearTimeout(filter.timer);filter.sequence++;filter.query='';filter.field.value=''};jpage=expensePage=contractPage=schedulePage=collectionPage=budgetPage=1;invoiceFilters.reset();invoiceQuery=invoiceState='';page=1;$('workspace').hidden=true;$('login').hidden=false;for(const id of ['rows','totals','milestone-rows','payment-invoice','invoice-mission','milestone-mission','expense-mission','expense-rows','cash-rows','contract-rows','schedule-rows','schedule-mission','aging-rows','collection-rows','forecast-rows','budget-rows'])$(id).replaceChildren();for(const id of ['milestone','invoice','payment','expense','schedule','planned-expense'])$(id).reset();notice('Déconnecté.')};$('lookup').onclick=()=>safe(lookup);
for(const [id,kind] of [['milestone','milestones'],['invoice','invoices'],['payment','payments']])$(id).onsubmit=e=>{e.preventDefault();safe(async()=>{const b=e.submitter;b.disabled=true;try{await api('billing/'+kind,'POST',Object.fromEntries(new FormData(e.target)));e.target.reset();await load();notice('Enregistrement effectué.')}finally{b.disabled=false}})};
$('prev').onclick=()=>{if(page>1){page--;safe(load)}};$('next').onclick=()=>{if(page*limit()<total){page++;safe(load)}};$('jprev').onclick=()=>{if(jpage>1){jpage--;safe(loadMilestones)}};$('jnext').onclick=()=>{if(jpage*limit()<jtotal){jpage++;safe(loadMilestones)}};
let expensePage=1,expenseTotal=0;
async function loadExpenses(){const filter=listFilters['expense-rows'],seq=++filter.sequence,t=token,d=await api('billing/expenses?'+new URLSearchParams({page:expensePage,q:filter.query,page_size:limit()}));if(!token||t!==token||seq!==filter.sequence)return;expenseTotal=d.total;$('cash-rows').replaceChildren();$('expense-rows').replaceChildren();for(const x of d.cash)row($('cash-rows'),[x.currency,x.received,x.outflows,x.net_flow]);for(const x of d.items)row($('expense-rows'),[x.reference,x.paid_date,x.category,x.amount+' '+x.currency,x.mission_title||'Sans mission',x.description]);$('epage').textContent='Page '+expensePage+' · '+expenseTotal+' dépense(s)';$('eprev').disabled=expensePage===1;$('enext').disabled=expensePage*limit()>=expenseTotal;}
$('expense').onsubmit=e=>{e.preventDefault();safe(async()=>{const b=e.submitter;b.disabled=true;try{await api('billing/expenses','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();expensePage=1;await Promise.all([loadExpenses(),loadForecast()]);notice('Décaissement enregistré.')}finally{b.disabled=false}})};
$('eprev').onclick=()=>{if(expensePage>1){expensePage--;safe(loadExpenses)}};$('enext').onclick=()=>{if(expensePage*limit()<expenseTotal){expensePage++;safe(loadExpenses)}};

let contractPage=1,contractTotal=0;
async function loadContracts(){const filter=listFilters['contract-rows'],seq=++filter.sequence,t=token,d=await api('billing/contracts?'+new URLSearchParams({page:contractPage,q:filter.query,page_size:limit()}));if(!token||t!==token||seq!==filter.sequence)return;contractTotal=d.total;$('contract-rows').replaceChildren();for(const x of d.items)row($('contract-rows'),[x.company+' / '+x.contract_ref+' / '+x.title,x.currency,x.planned,x.earned,x.invoiced,x.paid,x.balance,x.overdue,x.remaining_billable,x.actual_cost,x.earned_margin]);$('cpage').textContent='Page '+contractPage+' · '+contractTotal+' contrat(s)';$('cprev').disabled=contractPage===1;$('cnext').disabled=contractPage*limit()>=contractTotal}
$('cprev').onclick=()=>{if(contractPage>1){contractPage--;safe(loadContracts)}};$('cnext').onclick=()=>{if(contractPage*limit()<contractTotal){contractPage++;safe(loadContracts)}};

let schedulePage=1,scheduleTotal=0;
async function loadSchedule(){const filter=listFilters['schedule-rows'],seq=++filter.sequence,t=token,d=await api('billing/schedule?'+new URLSearchParams({page:schedulePage,q:filter.query,page_size:limit()}));if(!token||t!==token||seq!==filter.sequence)return;scheduleTotal=d.total;$('schedule-rows').replaceChildren();for(const x of d.items){const r=row($('schedule-rows'),[x.company+' / '+x.contract_ref,x.label+' / '+x.kind,x.amount+' '+x.currency,x.due_date,x.overdue?'Prévision dépassée':x.state+(x.invoice_reference?' / '+x.invoice_reference:''),'']);if(x.state==='PREVU'){const input=document.createElement('input');input.placeholder='Référence créance';input.setAttribute('aria-label','Référence créance');const link=document.createElement('button'),cancel=document.createElement('button');link.textContent='Rapprocher';cancel.textContent='Annuler';link.onclick=()=>safe(async()=>{await api('billing/schedule/'+x.id,'PATCH',{invoice_reference:input.value});await Promise.all([loadSchedule(),loadForecast()])});cancel.onclick=()=>safe(async()=>{if(confirm('Annuler cette prévision ?')){await api('billing/schedule/'+x.id,'PATCH',{state:'ANNULE'});await Promise.all([loadSchedule(),loadForecast()])}});r.lastChild.append(input,link,cancel)}}$('spage').textContent='Page '+schedulePage+' · '+scheduleTotal+' échéance(s)';$('sprev').disabled=schedulePage===1;$('snext').disabled=schedulePage*limit()>=scheduleTotal}
$('schedule').onsubmit=e=>{e.preventDefault();safe(async()=>{const b=e.submitter;b.disabled=true;try{await api('billing/schedule','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();schedulePage=1;await loadSchedule();notice('Échéance planifiée.')}finally{b.disabled=false}})};
$('sprev').onclick=()=>{if(schedulePage>1){schedulePage--;safe(loadSchedule)}};$('snext').onclick=()=>{if(schedulePage*limit()<scheduleTotal){schedulePage++;safe(loadSchedule)}};

let collectionPage=1,collectionTotal=0;
async function loadCollections(){
 const filter=listFilters['collection-rows'],seq=++filter.sequence,t=token,d=await api('billing/receivables?'+new URLSearchParams({page:collectionPage,q:filter.query,page_size:limit()}));if(!token||t!==token||seq!==filter.sequence)return;
 collectionTotal=d.total;for(const id of ['aging-rows','collection-rows'])$(id).replaceChildren();
 for(const [c,v] of Object.entries(d.aging))row($('aging-rows'),[c,v.current,v.d1_30,v.d31_60,v.d61_90,v.d90_plus]);
 for(const x of d.items){
  const r=row($('collection-rows'),[x.company+' / '+x.reference,x.balance+' '+x.currency,x.due_date,x.days_overdue,x.reminder_count+' · '+x.reminders.map(y=>y.created_at+' '+y.channel+' : '+y.note).join(' | '),'']);
  if(x.days_overdue>0){const channel=document.createElement('select');channel.setAttribute('aria-label','Canal de relance');for(const c of ['EMAIL','TELEPHONE','WHATSAPP','AUTRE'])channel.append(new Option(c,c));const note=document.createElement('input');note.maxLength=180;note.placeholder='Compte rendu';note.setAttribute('aria-label','Compte rendu de relance');const b=document.createElement('button');b.textContent='Consigner la relance';b.onclick=()=>safe(async()=>{if(!note.value.trim())return notice('Compte rendu obligatoire.');b.disabled=true;try{await api('billing/reminders','POST',{invoice_id:x.id,channel:channel.value,note:note.value});await loadCollections();notice('Relance consignée, aucun message envoyé.')}finally{b.disabled=false}});r.lastChild.append(channel,note,b)}
 }
 $('rpage').textContent='Page '+collectionPage+' · '+collectionTotal+' créance(s) ouverte(s)';$('rprev').disabled=collectionPage===1;$('rnext').disabled=collectionPage*limit()>=collectionTotal;
}
$('rprev').onclick=()=>{if(collectionPage>1){collectionPage--;safe(loadCollections)}};$('rnext').onclick=()=>{if(collectionPage*limit()<collectionTotal){collectionPage++;safe(loadCollections)}};

async function loadForecast(){const t=token,d=await api('billing/forecast');if(!token||t!==token)return;$('forecast-rows').replaceChildren();for(const x of d.items)row($('forecast-rows'),[x.currency,x.overdue,x.receipts_30,x.receipts_60,x.receipts_90,x.planned_30,x.planned_60,x.planned_90,x.recorded_outflows,x.outflows_30,x.outflows_60,x.outflows_90,x.net_30,x.net_60,x.net_90])}

let budgetPage=1,budgetTotal=0;
async function loadBudget(){const filter=listFilters['budget-rows'],seq=++filter.sequence,t=token,d=await api('billing/planned-expenses?'+new URLSearchParams({page:budgetPage,q:filter.query,page_size:limit()}));if(!token||t!==token||seq!==filter.sequence)return;budgetTotal=d.total;$('budget-rows').replaceChildren();
 for(const x of d.items){const r=row($('budget-rows'),[x.reference,x.amount+' '+x.currency,x.due_date,x.category,x.description,x.state+(x.expense_reference?' / '+x.expense_reference:''),'']);
  if(x.state==='PREVU'){const input=document.createElement('input');input.placeholder='Référence décaissement';input.setAttribute('aria-label','Référence décaissement');const link=document.createElement('button'),cancel=document.createElement('button');link.textContent='Rapprocher';cancel.textContent='Annuler';async function change(payload){link.disabled=cancel.disabled=true;try{await api('billing/planned-expenses/'+x.id,'PATCH',payload);await Promise.all([loadBudget(),loadForecast()])}finally{link.disabled=cancel.disabled=false}}link.onclick=()=>safe(()=>change({expense_reference:input.value}));cancel.onclick=()=>safe(async()=>{if(confirm('Annuler cette dépense prévisionnelle ?'))await change({state:'ANNULE'})});r.lastChild.append(input,link,cancel)}}
 $('bpage').textContent='Page '+budgetPage+' · '+budgetTotal+' prévision(s)';$('bprev').disabled=budgetPage===1;$('bnext').disabled=budgetPage*limit()>=budgetTotal;
}
$('planned-expense').onsubmit=e=>{e.preventDefault();safe(async()=>{const b=e.submitter;b.disabled=true;try{await api('billing/planned-expenses','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();budgetPage=1;await Promise.all([loadBudget(),loadForecast()]);notice('Dépense planifiée, aucun paiement effectué.')}finally{b.disabled=false}})};
$('bprev').onclick=()=>{if(budgetPage>1){budgetPage--;safe(loadBudget)}};$('bnext').onclick=()=>{if(budgetPage*limit()<budgetTotal){budgetPage++;safe(loadBudget)}};
let invoiceTimer;invoiceSearch.oninput=()=>{clearTimeout(invoiceTimer);if(!token)return;invoiceTimer=setTimeout(()=>{if(token)invoiceFilters.requestSubmit()},350)};invoiceStatus.onchange=()=>{clearTimeout(invoiceTimer);if(token)invoiceFilters.requestSubmit()};invoiceFilters.addEventListener('submit',()=>clearTimeout(invoiceTimer));$('logout').addEventListener('click',()=>clearTimeout(invoiceTimer));pageSize.onchange=()=>{page=jpage=expensePage=contractPage=schedulePage=collectionPage=budgetPage=1;if(token)safe(load)};

addListSearch('milestone-rows','Rechercher un jalon',()=>{jpage=1},loadMilestones);
addListSearch('expense-rows','Rechercher un décaissement',()=>{expensePage=1},loadExpenses);
addListSearch('contract-rows','Rechercher un contrat',()=>{contractPage=1},loadContracts);
addListSearch('schedule-rows','Rechercher une échéance',()=>{schedulePage=1},loadSchedule);
addListSearch('collection-rows','Rechercher une créance ouverte',()=>{collectionPage=1},loadCollections);
addListSearch('budget-rows','Rechercher une dépense prévisionnelle',()=>{budgetPage=1},loadBudget);
